{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]

    allocations = [segment["minimum"] for segment in segments]
    remaining = max(0, budget - sum(allocations))

    order = sorted(
        range(len(segments)),
        key=lambda index: (-segments[index]["importance"], index),
    )

    for index in order:
        if remaining == 0:
            break
        available = max(0, segments[index]["capacity"] - allocations[index])
        added = min(remaining, available)
        allocations[index] += added
        remaining -= added

    return {
        "allocations": allocations,
        "by_name": {
            segment["name"]: allocations[index]
            for index, segment in enumerate(segments)
        },
        "total": sum(allocations),
    }
"}
